// ==========================================
// EXPORTAR RUTINA COMO PDF (jsPDF)
// ==========================================
(function () {
    const LOGO_BASE64 = "data:image/png;base64,";

    function generateRoutinePDF(student) {
        const { jsPDF } = window.jspdf;
        const doc = new jsPDF({ unit: 'mm', format: 'a4' });

        const pageWidth = doc.internal.pageSize.getWidth();
        const pageHeight = doc.internal.pageSize.getHeight();
        const marginX = 18;
        let y = 0;

        const ORANGE = [255, 107, 0];
        const ORANGE_LIGHT = [255, 237, 222];
        const DARK = [18, 18, 20];
        const GRAY = [110, 110, 120];
        const TEXT = [30, 30, 34];
        const ROW_LINE = [232, 232, 236];

        function drawHeader() {
            doc.setFillColor(...DARK);
            doc.rect(0, 0, pageWidth, 32, 'F');
            doc.addImage(LOGO_BASE64, 'PNG', marginX, 4, 24, 24);
            doc.setTextColor(255, 255, 255);
            doc.setFont('helvetica', 'bold');
            doc.setFontSize(16);
            doc.text('VIDA CON SEBA', marginX + 30, 15);
            doc.setTextColor(...ORANGE);
            doc.setFont('helvetica', 'normal');
            doc.setFontSize(10.5);
            doc.text('Rutina de entrenamiento personalizada', marginX + 30, 22);
            y = 42;
        }

        function checkPageBreak(neededSpace) {
            if (y + neededSpace > pageHeight - 22) {
                doc.addPage();
                drawHeader();
            }
        }

        drawHeader();

        // Tarjeta de datos del alumno
        doc.setDrawColor(...ORANGE);
        doc.setFillColor(250, 247, 244);
        doc.roundedRect(marginX, y, pageWidth - marginX * 2, 20, 2, 2, 'FD');
        doc.setTextColor(...TEXT);
        doc.setFont('helvetica', 'bold');
        doc.setFontSize(13);
        doc.text(`¡Hola, ${student.nombre}!`, marginX + 6, y + 8);
        doc.setFont('helvetica', 'normal');
        doc.setFontSize(10);
        doc.setTextColor(...GRAY);
        doc.text(`Plan: ${student.plan}`, marginX + 6, y + 15);
        y += 30;

        // --- Configuración de la tabla ejercicio / series-reps ---
        const boxWidth = pageWidth - marginX * 2;
        const colExerciseWidth = boxWidth * 0.58;
        const colRepsWidth = boxWidth - colExerciseWidth;
        const colExerciseX = marginX;
        const colRepsX = marginX + colExerciseWidth;
        const cellPaddingX = 4;
        const titleBarHeight = 9;
        const headerRowHeight = 8.5;
        const rowLineHeight = 5;
        const rowVerticalPadding = 4;
        const GRID_LINE = [205, 205, 212];     // gris más visible para las líneas de la grilla
        const ROW_ALT = [244, 244, 246];       // fondo de fila alternada (zebra)

        student.rutina.forEach((item) => {
            doc.setFont('helvetica', 'normal');
            doc.setFontSize(9.5);

            // La fuente estándar del PDF no soporta el carácter "→"; separamos ejercicio y series/reps
            const rows = item.ejercicios.map((ej) => {
                const parts = ej.split('→');
                const nombre = (parts[0] || ej).trim();
                const repsYNotas = (parts[1] || '').trim();
                const nombreLines = doc.splitTextToSize(nombre, colExerciseWidth - cellPaddingX * 2);
                const repsLines = doc.splitTextToSize(repsYNotas, colRepsWidth - cellPaddingX * 2);
                const lineCount = Math.max(nombreLines.length, repsLines.length, 1);
                const rowHeight = lineCount * rowLineHeight + rowVerticalPadding;
                return { nombreLines, repsLines, rowHeight };
            });

            const rowsHeight = rows.reduce((sum, r) => sum + r.rowHeight, 0);
            const tableHeight = headerRowHeight + rowsHeight;
            const blockHeight = titleBarHeight + tableHeight;

            checkPageBreak(blockHeight);

            // Marco exterior de toda la tarjeta (barra + tabla), un solo borde prolijo
            doc.setDrawColor(...GRID_LINE);
            doc.setLineWidth(0.4);
            doc.roundedRect(marginX, y, boxWidth, blockHeight, 3, 3, 'S');

            // Barra de título naranja, calzada arriba de la tarjeta
            doc.setFillColor(...ORANGE);
            doc.roundedRect(marginX, y, boxWidth, titleBarHeight, 3, 3, 'F');
            doc.rect(marginX, y + titleBarHeight / 2, boxWidth, titleBarHeight / 2, 'F'); // cuadra las esquinas inferiores de la barra
            doc.setTextColor(255, 255, 255);
            doc.setFont('helvetica', 'bold');
            doc.setFontSize(11);
            doc.text(item.dia, marginX + 5, y + 6.2);

            // Encabezado de la tabla
            let cursorY = y + titleBarHeight;
            doc.setFillColor(...ORANGE_LIGHT);
            doc.rect(marginX, cursorY, boxWidth, headerRowHeight, 'F');
            doc.setTextColor(180, 75, 0);
            doc.setFont('helvetica', 'bold');
            doc.setFontSize(8.5);
            doc.text('EJERCICIO', colExerciseX + cellPaddingX, cursorY + 5.8);
            doc.text('SERIES x REPS', colRepsX + cellPaddingX, cursorY + 5.8);
            cursorY += headerRowHeight;

            // Línea firme debajo del encabezado
            doc.setDrawColor(...GRID_LINE);
            doc.setLineWidth(0.4);
            doc.line(marginX, cursorY, marginX + boxWidth, cursorY);

            // Filas de la tabla (con fondo alternado tipo zebra)
            rows.forEach((row, idx) => {
                if (idx % 2 === 1) {
                    doc.setFillColor(...ROW_ALT);
                    doc.rect(marginX, cursorY, boxWidth, row.rowHeight, 'F');
                }

                const textY = cursorY + rowVerticalPadding / 2 + rowLineHeight - 1.5;
                doc.setTextColor(...TEXT);
                doc.setFont('helvetica', 'normal');
                doc.setFontSize(9.5);
                doc.text(row.nombreLines, colExerciseX + cellPaddingX, textY);
                doc.setTextColor(...GRAY);
                doc.text(row.repsLines, colRepsX + cellPaddingX, textY);

                cursorY += row.rowHeight;

                // Línea separadora entre filas (no después de la última)
                if (idx < rows.length - 1) {
                    doc.setDrawColor(...GRID_LINE);
                    doc.setLineWidth(0.2);
                    doc.line(marginX, cursorY, marginX + boxWidth, cursorY);
                }
            });

            // Línea vertical divisoria entre columnas (a todo el alto de la tabla)
            doc.setDrawColor(...GRID_LINE);
            doc.setLineWidth(0.4);
            doc.line(colRepsX, y + titleBarHeight, colRepsX, y + blockHeight);

            y += blockHeight + 8; // separación entre tarjetas de días
        });

        // Pie de página en todas las hojas
        const pageCount = doc.internal.getNumberOfPages();
        for (let i = 1; i <= pageCount; i++) {
            doc.setPage(i);
            doc.setDrawColor(230, 230, 230);
            doc.line(marginX, pageHeight - 16, pageWidth - marginX, pageHeight - 16);
            doc.setFont('helvetica', 'normal');
            doc.setFontSize(8);
            doc.setTextColor(...GRAY);
            doc.text('Vida con Seba · Soporte activo por WhatsApp', marginX, pageHeight - 10);
            doc.text(`Página ${i} de ${pageCount}`, pageWidth - marginX, pageHeight - 10, { align: 'right' });
        }

        const safeName = student.nombre
            .toLowerCase()
            .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
            .replace(/\s+/g, '-');
        doc.save(`rutina-${safeName}.pdf`);
    }

    window.generateRoutinePDF = generateRoutinePDF;
})();
